package inventory

import (
	"reflect"
	"testing"
)

func TestReorderThreshold(t *testing.T) {
	items := []Item{{SKU: "below", Qty: 4}, {SKU: "at", Qty: 5}, {SKU: "above", Qty: 6}}
	want := []Item{{SKU: "below", Qty: 4}}
	if got := Reorder(items); !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder() = %v，想要 %v", got, want)
	}
}

func TestReorderTieBreakBySKU(t *testing.T) {
	items := []Item{
		{SKU: "b", Qty: 1},
		{SKU: "a", Qty: 1},
		{SKU: "c", Qty: 0},
	}
	want := []Item{
		{SKU: "c", Qty: 0},
		{SKU: "a", Qty: 1},
		{SKU: "b", Qty: 1},
	}
	if got := Reorder(items); !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder() = %v，想要 %v", got, want)
	}
}

func TestReorderEmpty(t *testing.T) {
	if got := Reorder(nil); len(got) != 0 {
		t.Fatalf("Reorder(nil) = %v，想要空结果", got)
	}
	if got := Reorder([]Item{}); len(got) != 0 {
		t.Fatalf("Reorder([]) = %v，想要空结果", got)
	}
}

