	items := []Item{{SKU: "b", Qty: 1}, {SKU: "a", Qty: 4}, {SKU: "z", Qty: 9}}
	orig := make([]Item, len(items))
	copy(orig, items)

	Reorder(items)

	if !reflect.DeepEqual(items, orig) {
		t.Fatalf("Reorder() 修改了入参：%v，想要 %v", items, orig)
	}
