package report

import (
	"fmt"

	"example.com/shop/inventory"
	"example.com/shop/pricing"
)

// LowStockLines 把待补货条目渲染成报表行，每行格式为
// "<sku> x<qty> = <金额>"，金额按 discountPct 折扣计算。
// 行顺序与 inventory.Reorder 一致（Qty 升序，Qty 同按 SKU 升序）。
func LowStockLines(items []inventory.Item, unitCents map[string]int, discountPct int) []string {
	low := inventory.Reorder(items)
	lines := make([]string, 0, len(low))
	for _, it := range low {
		amount := pricing.BulkTotal(unitCents[it.SKU], it.Qty, discountPct)
		lines = append(lines, fmt.Sprintf("%s = %d", SKULine(it.SKU, it.Qty), amount))
	}
	return lines
}
########## test ##########
package report

import (
	"reflect"
	"testing"

	"example.com/shop/inventory"
)

// TestLowStockLinesOrderAndDiscount 覆盖多条目排序与折扣金额：
// 只输出 Reorder 筛出的待补货条目，顺序为 Qty 升序、Qty 同按 SKU 升序，
// 金额 = BulkTotal(unitCents[sku], qty, discountPct)。
func TestLowStockLinesOrderAndDiscount(t *testing.T) {
	items := []inventory.Item{
		{SKU: "b", Qty: 4},
		{SKU: "a", Qty: 1},
		{SKU: "c", Qty: 1},
		{SKU: "d", Qty: 5}, // 达到阈值，不补货
		{SKU: "e", Qty: 0},
	}
	unitCents := map[string]int{
		"a": 100,
		"b": 250,
		"c": 250,
		"d": 999,
		"e": 1000,
	}
	want := []string{
		"e x0 = 0",   // 1000*0，折扣后仍为 0
		"a x1 = 75",  // 100 - 100*25/100
		"c x1 = 188", // 250 - 250*25/100 = 250-62，折扣向下取整
		"b x4 = 750", // 1000 - 1000*25/100
	}

	got := LowStockLines(items, unitCents, 25)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines() = %q，想要 %q", got, want)
	}
}

// TestLowStockLinesNoDiscount 覆盖 0 折扣时金额等于单价乘数量。
func TestLowStockLinesNoDiscount(t *testing.T) {
	items := []inventory.Item{{SKU: "x", Qty: 3}}
	got := LowStockLines(items, map[string]int{"x": 199}, 0)
	want := []string{"x x3 = 597"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines() = %q，想要 %q", got, want)
	}
}

// TestLowStockLinesEmpty 覆盖空输入以及没有待补货条目时返回长度 0 的结果。
func TestLowStockLinesEmpty(t *testing.T) {
	if got := LowStockLines(nil, nil, 10); len(got) != 0 {
		t.Fatalf("LowStockLines(nil) = %q，想要空结果", got)
	}
	if got := LowStockLines([]inventory.Item{}, map[string]int{}, 10); len(got) != 0 {
		t.Fatalf("LowStockLines([]) = %q，想要空结果", got)
	}
	allStocked := []inventory.Item{{SKU: "a", Qty: 5}, {SKU: "b", Qty: 9}}
	if got := LowStockLines(allStocked, map[string]int{"a": 100, "b": 100}, 10); len(got) != 0 {
		t.Fatalf("LowStockLines(全部达标) = %q，想要空结果", got)
	}
}
